def raises(error, function, *args):
    try:
        function(*args)
    except error:
        return True
    except Exception as other:
        raise AssertionError(f"expected {error.__name__}, got {type(other).__name__}: {other}")
    raise AssertionError(f"expected {error.__name__} to be raised")
def rounded(values, places=4):
    return [round(v, places) for v in values]
